package org.apache.pinot.segment.local.aggregator;

import java.util.List;
import org.apache.datasketches.cpc.CpcSketch;
import org.apache.datasketches.cpc.CpcUnion;
import org.apache.pinot.common.request.context.ExpressionContext;
import org.apache.pinot.segment.local.utils.CustomSerDeUtils;
import org.apache.pinot.segment.spi.AggregationFunctionType;
import org.apache.pinot.spi.data.FieldSpec.DataType;
import org.apache.pinot.spi.utils.CommonConstants;


/**
 * Aggregates {@code DISTINCTCOUNTCPCSKETCH} values while building the star-tree index.
 * <p>The intermediate aggregated value is kept as a {@link CpcUnion} so that repeated merges reuse the same union
 * instead of allocating a new one on every call. A single, un-merged value may still be represented as a bare
 * {@link CpcSketch}; both cases are handled transparently.
 */
public class DistinctCountCPCSketchValueAggregator implements ValueAggregator<Object, Object> {
  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;

  private final int _lgK;

  public DistinctCountCPCSketchValueAggregator(List<ExpressionContext> arguments) {
    // length 1 means we use the Helix default
    if (arguments.size() <= 1) {
      _lgK = CommonConstants.Helix.DEFAULT_CPC_SKETCH_LGK;
    } else {
      _lgK = arguments.get(1).getLiteral().getIntValue();
    }
  }

  @Override
  public AggregationFunctionType getAggregationType() {
    return AggregationFunctionType.DISTINCTCOUNTCPCSKETCH;
  }

  @Override
  public DataType getAggregatedValueType() {
    return AGGREGATED_VALUE_TYPE;
  }

  @Override
  public Object getInitialAggregatedValue(Object rawValue) {
    if (rawValue instanceof byte[]) { // Serialized Sketch
      return deserializeSketch((byte[]) rawValue);
    } else if (rawValue instanceof byte[][]) { // Multiple Serialized Sketches
      byte[][] serializedSketches = (byte[][]) rawValue;
      CpcUnion union = new CpcUnion(_lgK);
      for (byte[] bytes : serializedSketches) {
        union.update(deserializeSketch(bytes));
      }
      return union;
    } else {
      CpcSketch sketch = empty();
      addObjectToSketch(rawValue, sketch);
      return sketch;
    }
  }

  @Override
  public Object applyRawValue(Object value, Object rawValue) {
    CpcUnion union = asUnion(value);
    if (rawValue instanceof byte[]) {
      union.update(deserializeSketch((byte[]) rawValue));
    } else {
      CpcSketch sketch = empty();
      addObjectToSketch(rawValue, sketch);
      union.update(sketch);
    }
    return union;
  }

  @Override
  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
    CpcUnion union = asUnion(value);
    union.update(extractSketch(aggregatedValue));
    return union;
  }

  @Override
  public Object cloneAggregatedValue(Object value) {
    return deserializeSketch(serializeAggregatedValue(value));
  }

  @Override
  public int getMaxAggregatedValueByteSize() {
    // Static upper bound based on lgK (2580 for the default lgK=12). Using a static bound gives consistent memory
    // allocation regardless of the sketches observed so far.
    return CpcSketch.getMaxSerializedBytes(_lgK);
  }

  @Override
  public byte[] serializeAggregatedValue(Object value) {
    return CustomSerDeUtils.DATA_SKETCH_CPC_SER_DE.serialize(extractSketch(value));
  }

  @Override
  public Object deserializeAggregatedValue(byte[] bytes) {
    return deserializeSketch(bytes);
  }

  // Reuses the union if the value is already a CpcUnion, otherwise wraps the CpcSketch in a new CpcUnion.
  private CpcUnion asUnion(Object value) {
    if (value instanceof CpcUnion) {
      return (CpcUnion) value;
    }
    CpcUnion union = new CpcUnion(_lgK);
    union.update((CpcSketch) value);
    return union;
  }

  // Extracts the underlying CpcSketch from either a CpcUnion or a CpcSketch.
  private CpcSketch extractSketch(Object value) {
    return value instanceof CpcUnion ? ((CpcUnion) value).getResult() : (CpcSketch) value;
  }

  private CpcSketch deserializeSketch(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_CPC_SER_DE.deserialize(bytes);
  }

  private void addObjectToSketch(Object rawValue, CpcSketch sketch) {
    if (rawValue instanceof String) {
      sketch.update((String) rawValue);
    } else if (rawValue instanceof Integer) {
      sketch.update((Integer) rawValue);
    } else if (rawValue instanceof Long) {
      sketch.update((Long) rawValue);
    } else if (rawValue instanceof Double) {
      sketch.update((Double) rawValue);
    } else if (rawValue instanceof Float) {
      sketch.update((Float) rawValue);
    } else if (rawValue instanceof Object[]) {
      addObjectsToSketch((Object[]) rawValue, sketch);
    } else {
      throw new IllegalStateException(
          "Unsupported data type for CPC Sketch aggregation: " + rawValue.getClass().getSimpleName());
    }
  }

  private void addObjectsToSketch(Object[] rawValues, CpcSketch sketch) {
    if (rawValues instanceof String[]) {
      for (String s : (String[]) rawValues) {
        sketch.update(s);
      }
    } else if (rawValues instanceof Integer[]) {
      for (Integer i : (Integer[]) rawValues) {
        sketch.update(i);
      }
    } else if (rawValues instanceof Long[]) {
      for (Long l : (Long[]) rawValues) {
        sketch.update(l);
      }
    } else if (rawValues instanceof Double[]) {
      for (Double d : (Double[]) rawValues) {
        sketch.update(d);
      }
    } else if (rawValues instanceof Float[]) {
      for (Float f : (Float[]) rawValues) {
        sketch.update(f);
      }
    } else {
      throw new IllegalStateException(
          "Unsupported data type for CPC Sketch aggregation: " + rawValues.getClass().getSimpleName());
    }
  }

  private CpcSketch empty() {
    return new CpcSketch(_lgK);
  }
}
