package org.apache.pinot.segment.local.aggregator;

import org.apache.datasketches.theta.Sketch;
import org.apache.datasketches.theta.Sketches;
import org.apache.datasketches.theta.Union;
import org.apache.datasketches.theta.UpdateSketch;
import org.apache.pinot.segment.local.utils.CustomSerDeUtils;
import org.apache.pinot.segment.spi.AggregationFunctionType;
import org.apache.pinot.spi.data.FieldSpec.DataType;
import org.apache.pinot.spi.utils.CommonConstants;


/**
 * Aggregates {@code DISTINCTCOUNTTHETASKETCH} values while building the star-tree index.
 * <p>The intermediate aggregated value is kept as a {@link Union} so that repeated merges reuse the same union instead
 * of allocating a new one on every call. A single, un-merged value may still be represented as a bare {@link Sketch};
 * both cases are handled transparently.
 */
public class DistinctCountThetaSketchValueAggregator implements ValueAggregator<Object, Object> {
  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;

  private final int _nominalEntries;

  public DistinctCountThetaSketchValueAggregator() {
    // TODO: Handle configurable nominal entries for StarTreeBuilder
    _nominalEntries = CommonConstants.Helix.DEFAULT_THETA_SKETCH_NOMINAL_ENTRIES;
  }

  @Override
  public AggregationFunctionType getAggregationType() {
    return AggregationFunctionType.DISTINCTCOUNTTHETASKETCH;
  }

  @Override
  public DataType getAggregatedValueType() {
    return AGGREGATED_VALUE_TYPE;
  }

  @Override
  public Object getInitialAggregatedValue(Object rawValue) {
    if (rawValue instanceof byte[]) { // Serialized Sketch
      return deserializeSketch((byte[]) rawValue);
    } else if (rawValue instanceof byte[][]) { // Multiple Serialized Sketches
      byte[][] serializedSketches = (byte[][]) rawValue;
      Union union = newUnion();
      for (byte[] bytes : serializedSketches) {
        union.union(deserializeSketch(bytes));
      }
      return union;
    } else {
      return singleItemSketch(rawValue);
    }
  }

  @Override
  public Object applyRawValue(Object value, Object rawValue) {
    Union union = asUnion(value);
    if (rawValue instanceof byte[]) {
      union.union(deserializeSketch((byte[]) rawValue));
    } else {
      union.union(singleItemSketch(rawValue));
    }
    return union;
  }

  @Override
  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
    Union union = asUnion(value);
    union.union(extractSketch(aggregatedValue));
    return union;
  }

  @Override
  public Object cloneAggregatedValue(Object value) {
    return deserializeSketch(serializeAggregatedValue(value));
  }

  @Override
  public int getMaxAggregatedValueByteSize() {
    // Static upper bound: the number of bytes needed by a Union with the configured nominal entries. Using a static
    // bound gives consistent memory allocation regardless of the sketches observed so far.
    return newUnion().getCurrentBytes();
  }

  @Override
  public byte[] serializeAggregatedValue(Object value) {
    return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.serialize(extractSketch(value));
  }

  @Override
  public Object deserializeAggregatedValue(byte[] bytes) {
    return deserializeSketch(bytes);
  }

  // Reuses the union if the value is already a Union, otherwise wraps the Sketch in a new Union.
  private Union asUnion(Object value) {
    if (value instanceof Union) {
      return (Union) value;
    }
    Union union = newUnion();
    union.union((Sketch) value);
    return union;
  }

  // Extracts the underlying Sketch from either a Union or a Sketch.
  private Sketch extractSketch(Object value) {
    return value instanceof Union ? ((Union) value).getResult() : (Sketch) value;
  }

  private Union newUnion() {
    return Union.builder().setNominalEntries(_nominalEntries).buildUnion();
  }

  private Sketch deserializeSketch(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.deserialize(bytes);
  }

  // Utility method to create a theta sketch with one item in it
  private Sketch singleItemSketch(Object rawValue) {
    UpdateSketch sketch = Sketches.updateSketchBuilder().setNominalEntries(_nominalEntries).build();
